import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data.csv')
df['region']=df['region'].astype(int).astype('category'); df['tier']=df['tier'].astype('category')
controls = '+ log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)'
for y in ['dY_placebo','dY']:
    for spec in ['D', 'D + np.power(D,2)']:
        f=f'{y} ~ {spec} {controls}'
        res=smf.ols(f,df).fit(cov_type='HC3')
        print(y, spec, 'D coef p=', res.pvalues.get('D'), 'R2', round(res.rsquared,3))
        if 'np.power(D,2)' in spec:
            print(res.summary2().tables[1].loc[['D','np.power(D, 2)']])
        else:
            print(res.summary2().tables[1].loc[['D']])
